CREATE OR REPLACE FUNCTION public.guard_receipt_attachment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.company_module_access(NEW.company_id,'receipts') THEN RAISE EXCEPTION 'Receipt module is unavailable'; END IF; IF NEW.expense_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_receipts e WHERE e.id=NEW.expense_id AND e.company_id=NEW.company_id AND e.file_path=NEW.file_path AND e.page_count=NEW.page_count) THEN RAISE EXCEPTION 'Receipt attachment must match original evidence'; END IF; RETURN NEW; END $$;
CREATE TRIGGER receipt_evidence_guard BEFORE INSERT ON public.jobsheet_receipts FOR EACH ROW EXECUTE FUNCTION public.guard_receipt_attachment();
CREATE POLICY expense_file_failed_cleanup ON storage.objects FOR DELETE TO authenticated USING (bucket_id='job-receipts' AND owner_id=auth.uid()::text AND (storage.foldername(name))[1]=public.current_company_id()::text AND (storage.foldername(name))[2]='expenses' AND public.member_is_active(auth.uid()) AND NOT EXISTS (SELECT 1 FROM public.jobsheet_receipts r WHERE r.file_path=objects.name));